import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env=None):
    config = defaults.copy()
    if toml_path:
        with open(toml_path, 'rb') as f:
            config.update(tomllib.load(f))
    if env is None:
        env = os.environ
    for key, value in env.items():
        if key.startswith(env_prefix):
            path = key[len(env_prefix):].split('__')
            current = config
            for part in path[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[path[-1]] = value
    return config

import pytest
import envcfg
import os
import tomllib

def test_load_config_defaults():
    defaults = {'key': 'value'}
    config = envcfg.load_config(defaults)
    assert config == {'key': 'value'}

def test_load_config_toml():
    toml_content = b'key = "value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    config = envcfg.load_config({}, 'config.toml')
    assert config == {'key': 'value'}
    os.remove('config.toml')

def test_load_config_env():
    os.environ['APP__KEY'] = 'value'
    config = envcfg.load_config({}, env_prefix='APP__')
    assert config == {'key': 'value'}
    del os.environ['APP__KEY']

def test_load_config_precedence():
    defaults = {'key': 'default'}
    toml_content = b'key = "toml"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    os.environ['APP__KEY'] = 'env'
    config = envcfg.load_config(defaults, 'config.toml', env_prefix='APP__')
    assert config == {'key': 'env'}
    os.remove('config.toml')
    del os.environ['APP__KEY']

def test_load_config_coercion():
    os.environ['APP__KEY'] = '1'
    config = envcfg.load_config({'key': 0}, env_prefix='APP__')
    assert config == {'key': 1}
    del os.environ['APP__KEY']

def test_load_config_error():
    with pytest.raises(envcfg.ConfigError):
        envcfg.load_config({}, env_prefix='APP__')

