import os
import tomllib

class ConfigError(Exception):
    pass

def _coerce_value(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        value = value.lower()
        if value in ('true', '1', 'yes'):
            return True
        elif value in ('false', '0', 'no'):
            return False
        else:
            raise ConfigError(f'Invalid boolean value: {value}')
    else:
        return value

def load_config(defaults, toml_path=None, env_prefix=None, env=None):
    config = defaults.copy()
    if toml_path:
        with open(toml_path, 'rb') as f:
            config.update(tomllib.load(f))
    if env is None:
        env = os.environ
    for key, value in env.items():
        if env_prefix is not None and key.startswith(env_prefix):
            path = key[len(env_prefix):].replace('__', '_').lower().split('_')
            current = config
            for part in path[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            if path[-1] in defaults.get(''.join(path), {}):
                current[path[-1]] = _coerce_value(value, defaults.get(''.join(path)))
            else:
                raise ConfigError(f'No default for environment variable: {key}')
    return config
